-- 共30条国家级非遗项目数据

INSERT INTO heritage (name, category, location, level, inheritor, description, detail_description, cover_image, images, video_url, audio_url, phone, timeline, views, likes, favorites, create_time, update_time) VALUES
('剪纸艺术', '传统美术', '陕西', '国家级', '王秀英', '中国剪纸是用剪刀或刻刀在纸上剪刻花纹，用于装点生活或配合其他民俗活动的一种民间艺术。', '剪纸艺术是最古老的中国民间艺术之一，作为一种镂空艺术，它能给人以视觉上透空的感觉和艺术享受。剪纸用剪刀将纸剪成各种各样的图案，如窗花、门笺、墙花、顶棚花、灯花等。每逢过节或新婚喜庆，人们便将美丽鲜艳的剪纸贴在家中窗户、墙壁、门和灯笼上，节日的气氛也因此被烘托得更加热烈。陕西剪纸粗犷豪放，构图饱满，造型简练夸张，深受当地民众喜爱。', 'https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=800', '["https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=1200","https://images.unsplash.com/photo-1513569143478-b38b2c0ef97f?w=1200","https://images.unsplash.com/photo-1582555172866-f73bb12a2ab3?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"西汉","event":"剪纸艺术起源，最早用于祭祀和装饰"},{"year":"唐代","event":"剪纸艺术达到鼎盛，技艺更加精湛"},{"year":"宋代","event":"民间剪纸广泛流传，形成地方特色"},{"year":"明清","event":"剪纸成为民间必备的装饰艺术"},{"year":"2006年","event":"列入首批国家级非物质文化遗产名录"}]', 1286, 856, 5432, NOW(), NOW()),

('京剧', '传统戏剧', '北京', '国家级', '梅兰芳', '京剧是中国五大戏曲剧种之一，被视为中国国粹。', '京剧腔调以西皮、二黄为主，用胡琴和锣鼓等伴奏。角色分为生、旦、净、丑四大行。表演注重唱、念、做、打并重。京剧以其独特的艺术魅力被誉为"东方歌剧"，是中华文化的杰出代表。2006年列入首批国家级非物质文化遗产名录，2010年被列入人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1547534767-2efd3d12da4e?w=800', '["https://images.unsplash.com/photo-1547534767-2efd3d12da4e?w=1200","https://images.unsplash.com/photo-1606293926075-69a00dbfde81?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"1790年","event":"京剧形成于北京"},{"year":"1820年代","event":"京剧艺术基本成熟"},{"year":"1860年代","event":"京剧进入繁荣期"},{"year":"民国时期","event":"京剧走向鼎盛，名家辈出"},{"year":"2006年","event":"列入首批国家级非物质文化遗产名录"}]', 3421, 2134, 8765, NOW(), NOW()),

('景泰蓝制作技艺', '传统技艺', '北京', '国家级', '钱美华', '景泰蓝又称"铜胎掐丝珐琅"，是一种将铜丝掐成各种图案焊接在铜胎上，再填入珐琅釉料烧制而成的工艺美术品。', '景泰蓝制作工艺复杂，需经过制胎、掐丝、烧焊、点蓝、烧蓝、磨光、镀金等多道工序。其色彩丰富，以蓝为主色调，作品庄重典雅，富丽堂皇。景泰蓝既是实用器物，也是精美的艺术品，被誉为"中华国粹"。明代景泰年间制作的最为精美，故称"景泰蓝"。', 'https://images.unsplash.com/photo-1580481072645-022f9a6dbf27?w=800', '["https://images.unsplash.com/photo-1580481072645-022f9a6dbf27?w=1200","https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"元代","event":"景泰蓝工艺从阿拉伯地区传入中国"},{"year":"明代","event":"景泰年间达到鼎盛，蓝色珐琅最为著名"},{"year":"清代","event":"宫廷成立造办处，专制御用景泰蓝"},{"year":"1904年","event":"景泰蓝工艺品在国际博览会上获奖"},{"year":"2006年","event":"列入首批国家级非物质文化遗产名录"}]', 1876, 1245, 4321, NOW(), NOW()),

('龙泉青瓷烧制技艺', '传统技艺', '浙江', '国家级', '徐朝兴', '龙泉青瓷是中国陶瓷的杰出代表，以其"青如玉、明如镜、薄如纸、声如磬"的特点闻名于世。', '龙泉青瓷始于三国两晋，盛于宋代。其釉色青翠莹润，有粉青、梅子青等名贵品种。烧制工艺包括选料、成型、装饰、上釉、烧制等环节，需要精湛的技艺和丰富的经验。龙泉青瓷不仅具有实用价值，更是极具收藏价值的艺术品。2009年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=800', '["https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=1200","https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"三国两晋","event":"龙泉青瓷开始烧制"},{"year":"北宋","event":"龙泉青瓷技艺日趋成熟"},{"year":"南宋","event":"龙泉青瓷达到鼎盛，形成独特风格"},{"year":"明代","event":"龙泉窑成为著名瓷窑"},{"year":"2009年","event":"入选人类非物质文化遗产代表作名录"}]', 2134, 1567, 5678, NOW(), NOW()),

('古琴艺术', '传统音乐', '全国', '国家级', '李祥霆', '古琴是中国最古老的弹拨乐器之一，有三千多年的历史，被誉为"琴棋书画"四艺之首。', '古琴形制优美，音色深沉悠远，表现力丰富。其演奏技法复杂，有散、泛、按三种音色。古琴音乐追求"清、微、淡、远"的意境，是中国传统音乐美学的重要代表。古琴蕴含着深厚的中华文化内涵，是文人雅士修身养性的必修课。2003年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1510915361894-db8b60106cb1?w=800', '["https://images.unsplash.com/photo-1510915361894-db8b60106cb1?w=1200","https://images.unsplash.com/photo-1516567832553-9f06df2c6ee4?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"周代","event":"古琴已有3000多年历史"},{"year":"唐代","event":"古琴形制基本定型"},{"year":"宋代","event":"古琴艺术进入繁荣期"},{"year":"明代","event":"古琴流派纷呈"},{"year":"2003年","event":"入选人类非物质文化遗产代表作名录"}]', 1567, 987, 3456, NOW(), NOW()),

('端午节', '民俗', '全国', '国家级', '暂无', '端午节是中国传统节日，为纪念屈原而设，日期为农历五月初五。', '端午节习俗丰富，包括赛龙舟、吃粽子、挂艾草、佩香囊、喝雄黄酒等。龙舟竞渡是最具特色的活动，相传起源于楚国人划船救屈原。粽子用糯米包裹各种馅料，用竹叶或芦苇叶扎成。端午节不仅是一个节日，更是中华民族缅怀先贤、传承文化的重要载体。2009年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1520542023040-5c0cd7da3b91?w=800', '["https://images.unsplash.com/photo-1520542023040-5c0cd7da3b91?w=1200","https://images.unsplash.com/photo-1563091619-6b5c4e4a60b4?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"春秋时期","event":"端午节的起源与屈原相关"},{"year":"汉代","event":"端午成为固定节日"},{"year":"唐代","event":"端午节俗传播开来"},{"year":"明清","event":"龙舟竞渡成为端午重要活动"},{"year":"2009年","event":"入选人类非物质文化遗产代表作名录"}]', 4532, 2876, 9876, NOW(), NOW()),

('昆曲', '传统戏剧', '江苏', '国家级', '张继青', '昆曲是中国最古老的剧种之一，有"百戏之祖"的美誉，以其优美的唱腔和细腻的表演著称。', '昆曲形成于元末明初，以苏州为中心。其唱腔婉转细腻，行腔优美，水磨调清柔悠远。表演注重身段做派，一颦一笑皆有章法。昆曲文学价值极高，《牡丹亭》、《长生殿》等都是昆曲经典剧目。2001年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800', '["https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200","https://images.unsplash.com/photo-1547534767-2efd3d12da4e?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"元末明初","event":"昆曲形成于苏州地区"},{"year":"明代中叶","event":"魏良辅改革昆腔，创立水磨调"},{"year":"清代乾隆年间","event":"昆曲达到鼎盛，成为"时尚之曲""},{"year":"清末民初","event":"昆曲逐渐衰落"},{"year":"2001年","event":"入选人类非物质文化遗产代表作名录"}]', 2876, 1765, 6543, NOW(), NOW()),

('苏绣', '传统美术', '江苏', '国家级', '姚建萍', '苏绣是中国四大名绣之一，以精细雅洁著称，被誉为"东方艺术的明珠"。', '苏绣历史悠久，起源于苏州地区。其特点可以用"平、齐、细、密、匀、顺、和、光"八个字概括。技法丰富，有齐针、套针、戗针、乱针等四十多种。题材广泛，有人物、山水、花鸟、动物等。苏绣作品精美绝伦，具有很高的艺术价值和收藏价值。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=800', '["https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=1200","https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"春秋时期","event":"苏绣已有2000多年历史"},{"year":"宋代","event":"苏绣技艺日趋成熟，形成独特风格"},{"year":"明代","event":"苏绣成为著名绣种"},{"year":"清代","event":"苏绣进入鼎盛期，涌现出大量精品"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1987, 1234, 4567, NOW(), NOW()),

('太极拳', '传统体育', '河南', '国家级', '陈小旺', '太极拳是中国传统武术的代表，以柔克刚、借力打力著称，是一种内外兼修的传统拳术。', '太极拳起源于河南温县陈家沟，由陈王廷创编。其动作圆活连贯，轻柔缓慢，如行云流水。太极拳讲究意、气、神三者合一，具有强身健体、修身养性的功效。太极拳流派众多，主要有陈式、杨式、武式、吴式、孙式等。2020年，太极拳入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=800', '["https://images.unsplash.com/photo-1544367567-0f2fcb009e0b?w=1200","https://images.unsplash.com/photo-1599809275671-b5942cabc7a2?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"明末清初","event":"陈王廷创编太极拳"},{"year":"清代中叶","event":"太极拳在陈家沟代代相传"},{"year":"民国时期","event":"太极拳传播至全国各大城市"},{"year":"1956年","event":"国家体委编创二十四式简化太极拳"},{"year":"2020年","event":"入选人类非物质文化遗产代表作名录"}]', 3654, 2456, 7890, NOW(), NOW()),

('宣纸制作技艺', '传统技艺', '安徽', '国家级', '曹光华', '宣纸是中国传统的书画用纸，产于安徽宣城，因其优良的品质被誉为"纸中之王"。', '宣纸以青檀皮和沙田稻草为原料，经过108道工序手工制作而成。其特点是纹理清晰、质地绵韧、色泽白雅、润墨性强。有"轻似蝉翼白如雪，抖似细绸不闻声"的美誉。宣纸不仅是书画的理想材料，也是保存文献档案的最佳用纸，有"千年寿纸"之称。2009年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1585338107529-13afc5f02586?w=800', '["https://images.unsplash.com/photo-1585338107529-13afc5f02586?w=1200","https://images.unsplash.com/photo-1560485742-3b3b6e9a8c0f?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"唐代","event":"宣纸产于宣城地区"},{"year":"宋代","event":"宣纸制作技艺日趋完善"},{"year":"明代","event":"宣纸成为宫廷和文人墨客的首选用纸"},{"year":"清代","event":"宣纸制作达到鼎盛，品种繁多"},{"year":"2009年","event":"入选人类非物质文化遗产代表作名录"}]', 1432, 876, 3210, NOW(), NOW()),

('二十四节气', '民俗', '全国', '国家级', '暂无', '二十四节气是中国古代农耕文明的产物，反映了季节变化、气候特点和物候现象。', '二十四节气包括立春、雨水、惊蛰、春分、清明、谷雨、立夏、小满、芒种、夏至、小暑、大暑、立秋、处暑、白露、秋分、寒露、霜降、立冬、小雪、大雪、冬至、小寒、大寒。二十四节气指导着中国人民的农业生产和日常生活，是中国传统历法体系的重要组成部分。2016年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?w=800', '["https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?w=1200","https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"春秋时期","event":"古代天文数学家用土圭测日影，定出春分、秋分"},{"year":"战国时期","event":"增加夏至、冬至，形成四个节气"},{"year":"秦汉时期","event":"二十四节气逐步完善"},{"year":"汉武帝时期","event":"二十四节气正式列入历法"},{"year":"2016年","event":"入选人类非物质文化遗产代表作名录"}]', 2876, 1987, 6543, NOW(), NOW()),

('蜀绣', '传统美术', '四川', '国家级', '郝淑萍', '蜀绣是中国四大名绣之一，以其生动传神的图案和精细的针法著称。', '蜀绣又称"川绣"，起源于四川地区，历史悠久。其特点包括形象生动、绚丽多彩、虚实得体。针法技艺独特，有121种之多，以套针为主，配合纱针、铺针等技法。题材以花鸟虫鱼、人物走兽为主。蜀绣作品具有浓郁的地方特色和艺术风格。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=800', '["https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=1200","https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"春秋时期","event":"蜀绣已有2000多年历史"},{"year":"汉代","event":"蜀绣技艺达到较高水平"},{"year":"唐代","event":"蜀绣成为宫廷贡品"},{"year":"清代","event":"蜀绣进入鼎盛期，涌现众多佳作"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1654, 987, 3876, NOW(), NOW()),

('中医针灸', '传统医药', '全国', '国家级', '王雪苔', '中医针灸是中国传统医学的重要组成部分，包括针法和灸法，是一种通过刺激人体穴位来治疗疾病的方法。', '针灸理论以经络学说为核心，认为人体有365个穴位，分别属于十二经脉和奇经八脉。针法是用金属针刺入穴位，灸法是用艾绒燃烧熏烤穴位。针灸具有疏通经络、调和气血、平衡阴阳的作用，对多种疾病有显著疗效。2010年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?w=800', '["https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?w=1200","https://images.unsplash.com/photo-1559757148-5c350d0d3c56?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"新石器时代","event":"砭石是针灸的起源"},{"year":"春秋战国时期","event":"针灸理论开始形成"},{"year":"秦汉时期","event":"《黄帝内经》奠定针灸理论基础"},{"year":"宋代","event":"针灸教学体系完善，穴位逐步规范化"},{"year":"2010年","event":"入选人类非物质文化遗产代表作名录"}]', 2345, 1543, 5432, NOW(), NOW()),

('宜兴紫砂陶制作技艺', '传统技艺', '江苏', '国家级', '顾绍培', '宜兴紫砂陶是中国独特的陶瓷品种，以其独特的紫砂泥料和精湛的制作工艺著称。', '宜兴紫砂陶始于宋代，盛于明清。紫砂泥料是一种特殊的陶土，含有丰富的铁元素，烧制后呈紫红色或紫棕色。紫砂壶造型优美，款式繁多，有"方非一式，圆不一相"之说。紫砂壶具有良好的透气性和保温性，泡茶不走味，是茶具中的珍品。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=800', '["https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=1200","https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"宋代","event":"宜兴紫砂陶开始烧制"},{"year":"明代","event":"供春创制紫砂壶，技艺日趋成熟"},{"year":"清代","event":"紫砂壶进入鼎盛期，制壶名家辈出"},{"year":"民国时期","event":"紫砂壶艺继续发展"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1876, 1234, 4567, NOW(), NOW()),

('评弹艺术', '传统音乐', '江苏', '国家级', '蒋月泉', '评弹是苏州评话和弹词的总称，是一种以说唱为主的曲艺形式。', '苏州评话以说为主，辅以评，故事情节生动，人物形象鲜明。弹词则唱演并重，曲调优美，唱词文雅。评弹艺术语言生动风趣，表演细腻传神，具有浓郁的江南水乡特色。传统书目有《三国演义》、《水浒传》、《珍珠塔》等。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1516567832553-9f06df2c6ee4?w=800', '["https://images.unsplash.com/photo-1516567832553-9f06df2c6ee4?w=1200","https://images.unsplash.com/photo-1510915361894-db8b60106cb1?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"明代","event":"评弹起源于苏州地区"},{"year":"清代乾隆年间","event":"评弹艺术基本成型，名家辈出"},{"year":"近代","event":"蒋月泉改革评弹，创立"蒋调""},{"year":"当代","event":"评弹继续传承发展"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1432, 876, 2987, NOW(), NOW()),

('湘绣', '传统美术', '湖南', '国家级', '刘爱云', '湘绣是中国四大名绣之一，以其独特的虎头绣和鬅毛针技法著称。', '湘绣起源于湖南长沙地区，历史悠久。其特点包括形象生动、色彩丰富、针法独特。湘绣最具特色的技法是虎头绣和鬅毛针，能逼真地表现动物的毛发质感。题材以狮虎等猛兽、人物、花鸟为主。湘绣作品具有鲜明的地方特色和艺术风格。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=800', '["https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=1200","https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"春秋战国时期","event":"湘绣已有2000多年历史"},{"year":"汉代","event":"湘绣技艺达到较高水平"},{"year":"清代","event":"湘绣进入鼎盛期，形成独特风格"},{"year":"近代","event":"湘绣涌现众多刺绣大师"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1567, 943, 3654, NOW(), NOW()),

('粤剧', '传统戏剧', '广东', '国家级', '陈笑风', '粤剧是中国南方戏曲剧种之一，以广州话演唱，有"南国红豆"的美誉。', '粤剧形成于清代中叶，融合了唱、念、做、打等多种表演形式。其唱腔优美，板式丰富，有梆子、二黄两大声腔体系。表演注重武打和舞蹈，动作洗练大方。粤剧行当分为生、旦、丑、末、净等。经典剧目有《帝女花》、《紫钗记》等。2009年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1547534767-2efd3d12da4e?w=800', '["https://images.unsplash.com/photo-1547534767-2efd3d12da4e?w=1200","https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"明代","event":"弋阳腔传入广东，为粤剧前身"},{"year":"清代中叶","event":"粤剧在广东形成"},{"year":"清末民初","event":"粤剧进入繁荣期，涌现众多流派"},{"year":"1950年代","event":"粤剧进行改革，艺术水平提高"},{"year":"2009年","event":"入选人类非物质文化遗产代表作名录"}]', 1987, 1234, 4567, NOW(), NOW()),

('中国木拱桥传统营造技艺', '传统技艺', '福建', '国家级', '郑多金', '木拱桥是中国传统的桥梁建筑形式，不用一钉一铁，全凭榫卯嵌合。', '木拱桥又称"虹桥"，主要分布在福建、浙江等地。其结构巧妙，利用木料的抗压、抗拉特性，通过榫卯嵌合将木材连接成稳定的拱形结构。木拱桥造型优美，与周围山水环境和谐相融。著名的木拱桥有福建的鸾峰桥、浙江的溪东桥等。2009年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=800', '["https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=1200","https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"宋代","event":"木拱桥开始出现"},{"year":"明代","event":"木拱桥营造技艺日趋成熟"},{"year":"清代","event":"木拱桥遍布福建、浙江山区"},{"year":"当代","event":"木拱桥营造技艺得到保护和传承"},{"year":"2009年","event":"入选人类非物质文化遗产代表作名录"}]', 1234, 765, 2345, NOW(), NOW()),

('活字印刷术', '传统技艺', '全国', '国家级', '暂无', '活字印刷术是中国古代四大发明之一，由毕昇发明，是印刷史上的重大革命。', '活字印刷术发明于北宋庆历年间，采用胶泥刻字，单字排版，反复使用。其优点在于可以灵活排版，适合印刷多种书籍。活字印刷术比西方活字印刷早400多年，对世界文明的发展产生了深远影响。后来发展出木活字、金属活字等多种形式。2010年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1561287898-4f4c2c5e0e7e?w=800', '["https://images.unsplash.com/photo-1561287898-4f4c2c5e0e7e?w=1200","https://images.unsplash.com/photo-1585338107529-13afc5f02586?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"北宋庆历年间","event":"毕昇发明活字印刷术"},{"year":"元代","event":"王祯创制木活字"},{"year":"明代","event":"金属活字出现并广泛应用"},{"year":"清代","event":"活字印刷达到鼎盛"},{"year":"2010年","event":"入选人类非物质文化遗产代表作名录"}]', 1876, 1123, 3876, NOW(), NOW()),

('算盘', '传统技艺', '全国', '国家级', '暂无', '算盘是中国古代的计算工具，由算筹发展而来，是中华民族对人类文明的重大贡献。', '算盘呈长方形，由框、梁、杆、珠组成。一般为七珠算盘，上珠代表五，下珠代表一。算盘运算包括加减乘除，开方等，计算速度极快。算盘口诀朗朗上口，便于记忆。算盘不仅是计算工具，也蕴含着深刻的数学思想。2013年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1554244933-d876deb6b2ff?w=800', '["https://images.unsplash.com/photo-1554244933-d876deb6b2ff?w=1200","https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"东汉","event":"算盘雏形出现"},{"year":"唐代","event":"算盘形制基本定型"},{"year":"宋代","event":"算盘广泛使用，成为主流计算工具"},{"year":"明代","event":"珠算算法完善，出现大量算学著作"},{"year":"2013年","event":"列入国家级非物质文化遗产名录"}]', 987, 654, 1987, NOW(), NOW()),

('皮影戏', '传统戏剧', '陕西', '国家级', '汪天稳', '皮影戏是一种用兽皮制成的人物剪影进行表演的民间戏剧形式，有"电影的先驱"之称。', '皮影戏源于陕西华县，距今已有2000多年历史。制作皮影要经过选皮、刮皮、描样、雕刻、上色等十多道工序。表演时，艺人在白色幕布后操纵皮影，配合戏曲唱腔和音乐，讲述故事。皮影造型生动，色彩鲜艳，具有很高的艺术价值。2011年入选人类非物质文化遗产代表作名录。', 'https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=800', '["https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=1200","https://images.unsplash.com/photo-1513569143478-b38b2c0ef97f?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"西汉","event":"皮影戏起源，相传用于祭祀"},{"year":"唐代","event":"皮影戏用于宫廷娱乐"},{"year":"宋代","event":"皮影戏达到鼎盛，遍及民间"},{"year":"清代","event":"皮影戏传播至全国各地"},{"year":"2011年","event":"入选人类非物质文化遗产代表作名录"}]', 1654, 1032, 3654, NOW(), NOW()),

('花炮制作技艺', '传统技艺', '湖南', '国家级', '钟自力', '花炮是中国传统的鞭炮和烟花的总称，浏阳花炮以其精湛的工艺和绚丽的色彩闻名于世。', '浏阳花炮产于湖南浏阳，有1300多年历史。花炮制作包括提硝、炒药、制引、装药、封口、编结等数十道工序。其特点是燃放时声响效果好，色彩鲜艳，造型美观。烟花升空后能呈现出各种图案和文字，美不胜收。2006年，浏阳花炮入选国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1555943128-dfe9ef1c3a1f?w=800', '["https://images.unsplash.com/photo-1555943128-dfe9ef1c3a1f?w=1200","https://images.unsplash.com/photo-1513828583688-c52646db42da?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"唐代","event":"花炮起源于浏阳，用于祭祀"},{"year":"宋代","event":"花炮用于节庆和婚丧嫁娶"},{"year":"明代","event":"花炮制作技艺日趋成熟"},{"year":"清代","event":"浏阳花炮成为著名特产"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1123, 765, 2345, NOW(), NOW()),

('敦煌壁画', '传统美术', '甘肃', '国家级', '暂无', '敦煌壁画是敦煌艺术的重要组成部分，以其宏大的规模、精湛的技艺和深厚的文化内涵闻名于世。', '敦煌莫高窟始建于前秦时期，历经十六国、北魏、西魏、北周、隋、唐、五代、宋、西夏、元等朝代，形成巨大的石窟群。壁画内容丰富，包括佛像、菩萨、飞天、经变画、本生故事等。壁画色彩鲜艳，线条流畅，人物形象生动，是研究中国古代艺术和文化的重要资料。1987年，莫高窟被列入世界文化遗产名录。', 'https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=800', '["https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=1200","https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"前秦建元二年","event":"莫高窟开始营建"},{"year":"北魏时期","event":"壁画风格受印度犍陀罗艺术影响"},{"year":"唐代","event":"敦煌壁画达到鼎盛，技法成熟，色彩绚丽"},{"year":"西夏元代","event":"壁画继续发展，融入新元素"},{"year":"1987年","event":"莫高窟被列入世界文化遗产名录"}]', 3421, 2345, 8765, NOW(), NOW()),

('蜀锦织造技艺', '传统技艺', '四川', '国家级', '叶永洲', '蜀锦是中国四大名锦之一，以其绚丽的色彩、独特的纹样和精湛的织造技艺著称。', '蜀锦产于四川成都，有两千多年历史。其织造技艺复杂，需在花楼织机上由两人配合操作，一人拉花，一人投梭送纬。蜀锦图案丰富，有几何纹、花鸟纹、人物故事等。色彩以红、蓝、黄、绿为主，鲜艳华丽。蜀锦不仅是精美的工艺品，也是研究蜀文化的重要实物资料。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=800', '["https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=1200","https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"春秋战国时期","event":"蜀锦已有2000多年历史"},{"year":"汉代","event":"蜀锦成为著名织锦品种"},{"year":"唐代","event":"蜀锦织造技艺达到鼎盛"},{"year":"宋代","event":"蜀锦图案创新，品种繁多"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1432, 876, 3210, NOW(), NOW()),

('中医正骨疗法', '传统医药', '全国', '国家级', '罗有名', '中医正骨疗法是通过手法复位、夹板固定、药物治疗等方法治疗骨折、关节脱位等疾病的中医特色疗法。', '正骨疗法历史悠久，起源于古代中医伤科。其特点是注重整体观念，强调筋骨并重。通过望、闻、问、切四诊合参，诊断病情。手法的运用是正骨的核心，包括摸、接、端、提、推、拿、按、摩等。正骨疗法对骨折、关节脱位、软组织损伤等有显著疗效。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1559757148-5c350d0d3c56?w=800', '["https://images.unsplash.com/photo-1559757148-5c350d0d3c56?w=1200","https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"周代","event":"正骨疗法已有记载"},{"year":"隋代","event":"《诸病源候论》记载正骨方法"},{"year":"唐代","event":"正骨成为专科"},{"year":"清代","event":"《医宗金鉴》总结正骨经验"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1654, 1032, 3876, NOW(), NOW()),

('黄酒酿造技艺', '传统技艺', '浙江', '国家级', '钱兴华', '黄酒是中国特有的传统酿造酒，以其醇厚的口感和丰富的营养价值被誉为"液体蛋糕"。', '绍兴黄酒产于浙江绍兴，有2500多年历史。采用优质糯米和鉴湖水为原料，经过浸米、蒸饭、落缸、开耙、压榨、煎酒等工序，自然发酵而成。黄酒含有多氨基酸、微量元素等营养成分，具有舒筋活血、美容养颜的功效。绍兴黄酒品种繁多，有加饭酒、善酿酒、香雪酒等。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800', '["https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200","https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"春秋时期","event":"黄酒酿造已有2500多年历史"},{"year":"宋代","event":"黄酒酿造技艺日趋成熟"},{"year":"清代","event":"绍兴黄酒成为著名特产"},{"year":"1915年","event":"绍兴黄酒在美国巴拿马万国博览会上获金奖"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1234, 765, 2345, NOW(), NOW()),

('河南坠子', '传统音乐', '河南', '国家级', '陈梅生', '河南坠子是由河南坠子为基础发展而成的曲艺形式，以其独特的唱腔和表演风格著称。', '河南坠子形成于清代末年，主要流布于河南及周边地区。其唱腔粗犷豪放，旋律优美，有"一泻千里"之势。表演形式灵活，有单口、对口、群口等多种形式。坠子书内容丰富，有历史故事、民间传说、公案侠义等题材。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1516567832553-9f06df2c6ee4?w=800', '["https://images.unsplash.com/photo-1516567832553-9f06df2c6ee4?w=1200","https://images.unsplash.com/photo-1510915361894-db8b60106cb1?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"清代末年","event":"河南坠子形成于河南地区"},{"year":"民国时期","event":"坠子广泛流传于中原地区"},{"year":"1950年代","event":"河南坠子进行改革，艺术水平提高"},{"year":"当代","event":"河南坠子继续传承发展"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 987, 654, 1876, NOW(), NOW()),

('茅台酒酿造技艺', '传统技艺', '贵州', '国家级', '季克良', '茅台酒是中国酱香型白酒的典型代表，以其独特的风味和卓越的品质被誉为"国酒"。', '茅台酒产于贵州仁怀茅台镇，有800多年历史。采用优质高粱为原料，经过九次蒸煮、八次发酵、七次取酒等复杂工艺，自然发酵而成。茅台酒具有酱香突出、幽雅细腻、酒体醇厚、回味悠长等特点。其酿造技艺独特，是中华民族智慧的结晶。2014年，茅台酒酿造技艺列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800', '["https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200","https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"西汉","event":"茅台镇已有酿酒历史"},{"year":"1915年","event":"茅台酒在美国巴拿马万国博览会上获金奖"},{"year":"1935年","event":"长征途中红军与茅台镇结缘"},{"year":"1949年","event":"茅台酒成为开国大典国宴用酒"},{"year":"2014年","event":"茅台酒酿造技艺列入国家级非物质文化遗产名录"}]', 2876, 1876, 5432, NOW(), NOW()),

('泥人张彩塑', '传统美术', '天津', '国家级', '张明达', '泥人张彩塑是天津的传统民间艺术，以其精湛的塑形技艺和绚丽的彩绘风格著称。', '泥人张彩塑起源于天津，由张明山创立于清代道光年间。其特点是将雕塑与彩绘完美结合，人物形象生动逼真，色彩鲜艳和谐。泥人张彩塑题材广泛，有戏曲人物、民间故事、市井生活等。制作工艺包括和泥、捏制、彩绘等步骤。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=800', '["https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=1200","https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"清代道光年间","event":"张明山创立泥人张彩塑"},{"year":"清代","event":"泥人张彩塑技艺代代相传"},{"year":"近代","event":"泥人张彩塑进入鼎盛期"},{"year":"当代","event":"泥人张彩塑继续传承发展"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1123, 765, 2987, NOW(), NOW()),

('杨柳青木板年画', '传统美术', '天津', '国家级', '霍庆顺', '杨柳青木板年画是中国著名的木版年画之一，以其细腻的刻工、鲜艳的色彩和丰富的内容著称。', '杨柳青年画产于天津西青区杨柳青镇，有600多年历史。其制作工艺包括刻版、印刷、手绘上色等环节。年画内容丰富，有门神、仕女、娃娃、戏曲人物、山水花鸟等。色彩鲜艳，线条细腻，构图饱满，富有浓郁的民间艺术特色。2006年列入国家级非物质文化遗产名录。', 'https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=800', '["https://images.unsplash.com/photo-1519677100203-a0e668c92439?w=1200","https://images.unsplash.com/photo-1582562124811-c09020d0a2cb?w=1200"]', 'https://www.w3schools.com/html/mov_bbb.mp4', 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', NULL, '[{"year":"明代","event":"杨柳青年画开始兴起"},{"year":"清代乾隆年间","event":"杨柳青年画达到鼎盛"},{"year":"清代晚期","event":"杨柳青年画遍及北方地区"},{"year":"近代","event":"杨柳青年画进行改革创新"},{"year":"2006年","event":"列入国家级非物质文化遗产名录"}]', 1098, 687, 2345, NOW(), NOW());
